CREATE TABLE IF NOT EXISTS rentall."DenunciasAnuncio" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "AnuncioId" integer NOT NULL REFERENCES rentall."Anuncios"(id) ON DELETE CASCADE,
  "AutorId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
  "Motivo" varchar(50) NOT NULL,
  "Detalhes" varchar(700),
  "Estado" varchar(24) NOT NULL DEFAULT 'Pendente'
    CHECK ("Estado" IN ('Pendente','Revista')),
  "CriadaEm" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UX_Denuncia_Anuncio_Autor" UNIQUE ("AnuncioId","AutorId")
);
CREATE INDEX IF NOT EXISTS "IX_Denuncias_Estado" ON rentall."DenunciasAnuncio" ("Estado","CriadaEm" DESC);
REVOKE ALL ON rentall."DenunciasAnuncio" FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE rentall."DenunciasAnuncio_Id_seq" FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON rentall."DenunciasAnuncio" TO rentall_app;
GRANT USAGE, SELECT ON SEQUENCE rentall."DenunciasAnuncio_Id_seq" TO rentall_app;
